with flattened as (select id, created_at, coupon_codes, item.price, item.promo from (select id, created_at, coupon_codes, explode_outer(items) as item from carts) li) select date_trunc('day', created_at) as activity_day, size(collect_set(promo)) as num_promos, (unix_timestamp(max(created_at)) - unix_timestamp(min(created_at))) / 60 as span_minutes, count(*) as cnt, sort_array(collect_set(promo)) as promo_list, avg(price) as avg_price from flattened group by date_trunc('day', created_at) order by num_promos desc;
